from collections import defaultdict

def print_next_greater_freq(arr, n):
    freq = defaultdict(int)
    for num in arr:
        freq[num] += 1

    answer = [-1] * n
    stack = []

    for i in range(n-1, -1, -1):
        current_freq = freq[arr[i]]
        while stack and freq[stack[-1]] <= current_freq:
            stack.pop()

        if stack:
            answer[i] = stack[-1]

        stack.append(arr[i])

    return answer
